function zustandLesen() {
  try {
    const roh = JSON.parse(window.sessionStorage.getItem(SPEICHER_SCHLUESSEL) || "null");
    if (!roh || typeof roh !== "object") return null;
    const land = LAENDER.some((l) => l.id === roh.land) ? roh.land : null;
